import selectors, socket

sel = selectors.DefaultSelector()                  # best selector for this platform

def accept(sock, _):
    conn, _ = sock.accept(); conn.setblocking(False)
    sel.register(conn, selectors.EVENT_READ, read)  # handler attached as key.data

def read(conn, _):
    data = conn.recv(4096)
    if not data: sel.unregister(conn); conn.close()

while True:
    for key, mask in sel.select():                  # demultiplex, then dispatch
        key.data(key.fileobj, mask)
